CREATE COLUMN TABLE "TEST_AP"."IPD2" ("DocEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "ChildNum" INTEGER CS_INT NOT NULL , "BarCode" NVARCHAR(254) NOT NULL , "UomCode" NVARCHAR(20) NOT NULL , "UomQty" DECIMAL(21,6) CS_FIXED, "CountQty" DECIMAL(21,6) CS_FIXED, "Tk1UomQty" DECIMAL(21,6) CS_FIXED, "Tk2UomQty" DECIMAL(21,6) CS_FIXED, "Tk1CntQty" DECIMAL(21,6) CS_FIXED, "Tk2CntQty" DECIMAL(21,6) CS_FIXED, "ItmsPerUnt" DECIMAL(21,6) CS_FIXED, "LogIns" INTEGER CS_INT, "UgpEntry" INTEGER CS_INT, "TeamUomQty" DECIMAL(21,6) CS_FIXED, "TeamCntQty" DECIMAL(21,6) CS_FIXED, "IUomEntry" NVARCHAR(20), PRIMARY KEY ("DocEntry", "LineNum", "ChildNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
